#include <iostream>
#include <memory>

class LecturaOpcional {
public:
    LecturaOpcional() = default;
    explicit LecturaOpcional(int numero) : dato_{std::make_unique<int>(numero)} {}
    void cargar(int numero) { dato_ = std::make_unique<int>(numero); }
    void vaciar() noexcept { dato_.reset(); }
    const int* acceso() const noexcept { return dato_.get(); }
    bool leer(int& numero) const noexcept {
        if (!dato_) { return false; }
        numero = *dato_;
        return true;
    }
    void escribir(std::ostream& salida) const {
        if (dato_) { salida << *dato_; }
        else { salida << "Vacio"; }
    }
    bool operator==(const LecturaOpcional& otra) const;
private:
    std::unique_ptr<int> dato_{};
};
bool LecturaOpcional::operator==(const LecturaOpcional& otra) const {
    // Define la igualdad de contenido, incluyendo ambos estados de presencia.
    return dato_ == otra.dato_;
}
struct Observacion {
    bool presente;
    int numero;
    const int* direccion;
    bool operator==(const Observacion&) const = default;
};

Observacion observar(const LecturaOpcional& lectura) {
    Observacion estado{false, 0, lectura.acceso()};
    estado.presente = lectura.leer(estado.numero);
    return estado;
}
int main() {
    int ordenes = 0;
    if (!(std::cin >> ordenes) || ordenes < 1 || ordenes > 12) { return 1; }
    LecturaOpcional a{8}, b{8};
    for (int i = 0; i < ordenes; ++i) {
        int op = 0, valor = 0;
        if (!(std::cin >> op >> valor)) { return 1; }
        const char* estado = "Aceptada";
        if (op == 1) { a.cargar(valor); }
        else if (op == 2) { b.cargar(valor); }
        else if (op == 3) { a.vaciar(); }
        else if (op == 4) { b.vaciar(); }
        else if (op != 5) { estado = "Operacion"; }
        const Observacion antesA = observar(a), antesB = observar(b);
        const LecturaOpcional& izquierda = a;
        const LecturaOpcional& derecha = b;
        const bool iguales = (izquierda == derecha);
        const bool distintos = (izquierda != derecha);
        const bool vuelta = (derecha == izquierda);
        const bool propiaA = (izquierda == izquierda);
        const bool propiaB = (derecha == derecha);
        const bool mismaDireccion = (a.acceso() == b.acceso());
        const bool conservado = (antesA == observar(a) && antesB == observar(b));
        std::cout << "Estado:" << estado << ";Iguales:" << iguales << ";Distintos:" << distintos
                  << ";Vuelta:" << vuelta << ";AutoA:" << propiaA << ";AutoB:" << propiaB
                  << ";MismaDireccion:" << mismaDireccion << ";Conservado:" << conservado << ";A:";
        a.escribir(std::cout);
        std::cout << ";B:";
        b.escribir(std::cout);
        std::cout << '\n';
    }
    std::cout << "FinalA:";
    a.escribir(std::cout);
    std::cout << ";FinalB:";
    b.escribir(std::cout);
    return 0;
}

